def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    if op_c == 0:
        return 'D'
    if op_d == 0:
        return 'C'
    if n >= 10:
        last10 = op[-10:]
        for shift in range(5):
            match = True
            for i in range(10):
                pos = (i - shift) % 5
                expected = 'D' if pos in (0, 1) else 'C'
                if last10[i] != expected:
                    match = False
                    break
            if match:
                return 'D'
    last = op[-1]
    run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            run += 1
        else:
            break
    if run >= 4:
        if op_d * 2 > n:
            return 'D'
        return 'C'
    if run >= 2:
        return 'D'
    if run == 1:
        if op_c > op_d * 2:
            return 'C'
        return 'D'
    if op_c * 5 >= n * 4:
        return 'C'
    if op_d * 2 > n:
        return 'D'
    return 'C'
